package care.tend.focus;
import care.tend.common.CurrentUser;import care.tend.item.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController@RequestMapping("/api/focus-sessions")public class FocusController{private final JdbcTemplate jdbc;private final LifeItemRepository items;public FocusController(JdbcTemplate jdbc,LifeItemRepository items){this.jdbc=jdbc;this.items=items;}public record Start(@NotNull UUID taskId,@Min(1)@Max(240)int plannedMinutes){}public record Finish(String outcome,@Size(max=2000)String reflection){}public record Session(UUID id,UUID taskId,String taskTitle,UUID categoryId,int plannedMinutes,int actualSeconds,String status,String outcome,String reflection,Instant startedAt,Instant updatedAt){}
 @PostMapping@Transactional Session start(@Valid@RequestBody Start r){var uid=CurrentUser.id();items.findByIdAndUserId(r.taskId(),uid).filter(i->i.type==LifeItem.Type.TASK).orElseThrow();if(!jdbc.queryForList("select id from focus_session where user_id=? and status in ('ACTIVE','PAUSED')",uid).isEmpty())throw new IllegalArgumentException("Finish or resume your current focus session first");var id=jdbc.queryForObject("insert into focus_session(user_id,task_id,planned_minutes,status) values (?,?,?,'ACTIVE') returning id",UUID.class,uid,r.taskId(),r.plannedMinutes());return one(uid,id);}
 @GetMapping("/active")ResponseEntity<Session>active(){var uid=CurrentUser.id();var ids=jdbc.query("select id from focus_session where user_id=? and status in ('ACTIVE','PAUSED')",(rs,n)->rs.getObject(1,UUID.class),uid);return ids.isEmpty()?ResponseEntity.noContent().build():ResponseEntity.ok(one(uid,ids.get(0)));}
 @PostMapping("/{id}/pause")@Transactional Session pause(@PathVariable UUID id){var uid=CurrentUser.id();int n=jdbc.update("update focus_session set actual_seconds=actual_seconds+extract(epoch from (now()-updated_at))::int,status='PAUSED',paused_at=now(),updated_at=now() where id=? and user_id=? and status='ACTIVE'",id,uid);if(n==0)throw new NoSuchElementException("Active focus session not found");return one(uid,id);}
 @PostMapping("/{id}/resume")@Transactional Session resume(@PathVariable UUID id){var uid=CurrentUser.id();int n=jdbc.update("update focus_session set status='ACTIVE',paused_at=null,updated_at=now() where id=? and user_id=? and status='PAUSED'",id,uid);if(n==0)throw new NoSuchElementException("Paused focus session not found");return one(uid,id);}
 @PostMapping("/{id}/finish")@Transactional Session finish(@PathVariable UUID id,@RequestBody Finish r){var uid=CurrentUser.id();int n=jdbc.update("update focus_session set actual_seconds=actual_seconds+case when status='ACTIVE' then extract(epoch from (now()-updated_at))::int else 0 end,status='FINISHED',outcome=?,reflection=?,finished_at=now(),updated_at=now() where id=? and user_id=? and status in ('ACTIVE','PAUSED')",r.outcome(),r.reflection(),id,uid);if(n==0)throw new NoSuchElementException("Focus session not found");return one(uid,id);}
 @GetMapping List<Session>history(@RequestParam(defaultValue="7")@Min(1)@Max(365)int days){var uid=CurrentUser.id();return jdbc.query(select()+" where f.user_id=? and f.started_at>=now()-(?*interval '1 day') order by f.started_at desc",mapper(),uid,days);}
 private Session one(UUID uid,UUID id){return jdbc.queryForObject(select()+" where f.user_id=? and f.id=?",mapper(),uid,id);}private String select(){return"select f.id,f.task_id,i.title,i.category_id,f.planned_minutes,f.actual_seconds+case when f.status='ACTIVE' then extract(epoch from (now()-f.updated_at))::int else 0 end,f.status,f.outcome,f.reflection,f.started_at,f.updated_at from focus_session f join life_item i on i.id=f.task_id";}private org.springframework.jdbc.core.RowMapper<Session>mapper(){return(rs,n)->new Session(rs.getObject(1,UUID.class),rs.getObject(2,UUID.class),rs.getString(3),rs.getObject(4,UUID.class),rs.getInt(5),rs.getInt(6),rs.getString(7),rs.getString(8),rs.getString(9),rs.getTimestamp(10).toInstant(),rs.getTimestamp(11).toInstant());}}
